fn inspect(values: Vec[int], present: bool) { println(values.len())
 println(present) }
fn main() {
 var values = [1, 2]
 inspect(values, values.pop().isSome())
}

fn work(present: bool) {
 let owner = "owned".toString()
 var value: ?int = none
 if present { value = 4 }
 println(value ?? [owner].len())
}
fn main() { work(true)
 work(false) }

fn work(value: ?int) {
 let owner = "owned".toString()
 let count = value ?? [owner].len()
 println(owner)
 println(count)
}
fn main() {}

fn main() { let first: ?int = none
 let second: ?int = 2
 println(first ?? second ?? 3) }

fn source(flag: bool) -> ?int {
 if flag { return 7 }
 return none
}
fn take(value: ?int) { println(value.isSome())
 println(value.isNone()) }
fn main() {
 let inferred = some(0)
 take(inferred)
 take(1)
 take(none)
 var assigned: ?int = none
 assigned = 2
 take(assigned)
 assigned = none
 take(assigned)
 take(source(true))
 take(source(false))
}

